mapper.select:
select count(*) from rp_cr

	1 = 1

		and update_time >= #{before_date}


		and update_time < #{after_date}

select record_id,Gene,lang,Mutation,ori_mutation,Clinical_significance,GeneDesc,VarClianno,has_drug,updated_by,date_format(update_time,'%Y-%m-%d %H:%i:%s') as update_time,date_format(check_date,'%Y-%m-%d %H:%i:%s') as check_date 
from rp_cr

	1 = 1

		and update_time >= #{before_date}


		and update_time < #{after_date}


limit #{pageNo},#{pageSize}

select Gene, lang, Mutation, ori_mutation, case Clinical_significance WHEN '1' then '致病' WHEN '2' THEN '可能致病' WHEN '3' THEN '临床意义未明' WHEN '4' THEN '可能良性' WHEN '5' THEN '良性' END AS Clinical_significance, GeneDesc, VarClianno, has_drug, updated_by, date_format(update_time, '%Y-%m-%d %H:%i:%s') AS update_time, date_format(check_date,'%Y-%m-%d %H:%i:%s') as check_date from rp_cr
1 = 1
and update_time >= #{before_date}
and update_time < #{after_date}
